vrs_set_all = {
	set_variable = vrs_scalar
	set_variable = { name = vrs_block value = 1 }
	set_variable = vrs_inline
	set_global_variable = vrs_global
	set_local_variable = vrs_local
	set_dead_character_variable = vrs_dead
	set_variable = vrs_truly_dead
}

namespace = vrs
vrs.1 = {
	desc = vrs.1.desc
	trigger = { vrs_reads_trigger = yes }
	immediate = {
		has_variable = { name = vrs_block }
		add_gold = var:vrs_inline
		add_gold = global_var:vrs_global
		add_gold = local_var:vrs_local
		add_gold = dead_var:vrs_dead
	}
	option = { name = vrs.1.a }
}
